<?php
namespace App\Services;
use App\Models\Upload;use Illuminate\Support\Facades\{DB,Cache};
/** Durable, idempotent cleanup; queue jobs and the scheduled fallback share leases. */
class ProductMediaCleanup {
 const TABLE='footstep_product_media_cleanup';
 public static function relative($value){if(!is_string($value)||$value==='')return null;$v=html_entity_decode($value,ENT_QUOTES);$parts=parse_url($v);if($parts===false)return null;if(isset($parts['host'])&&!in_array(strtolower($parts['host']),array_filter([strtolower((string)parse_url(config('app.url'),PHP_URL_HOST)),'footsteponline.com','www.footsteponline.com']),true))return null;$v=rawurldecode($parts['path']??$v);$v=ltrim($v,'/');if(strpos($v,'public/')===0)$v=substr($v,7);if(strpos($v,'uploads/')!==0||strpos($v,'..')!==false||strpos($v,'\\')!==false||strpos($v,"\0")!==false)return null;foreach(explode('/',$v)as $part)if($part===''||$part[0]==='.')return null;if(preg_match('/\.(php[0-9]?|phtml|phar)$/iD',$v))return null;return $v;}
 private static function local($relative){if(self::relative($relative)!==$relative)throw new \RuntimeException('Unsafe upload path retained.');$root=public_path();foreach(explode('/',$relative)as $part){$root.='/'.$part;if(is_link($root))throw new \RuntimeException('Upload symlink retained.');}return $root;}
 private static function variants($relative){$paths=[];$m=ImageVariantManifest::read($relative);if($m)foreach($m['variants']as $v)$paths[]=$v;try{$file=self::local($relative);if(is_file($file)){foreach(['responsive-v2-q90:','responsive-v2:','responsive-v1:']as $prefix){$key=substr(hash('sha256',$prefix.$relative.':'.filemtime($file).':'.filesize($file)),0,32);foreach(glob(public_path('uploads/optimized/'.$key.'-*'))?:[]as $v)$paths[]='uploads/optimized/'.basename($v);}}}catch(\Throwable $e){}return array_values(array_unique(array_filter($paths,fn($v)=>preg_match('~^uploads/optimized/[a-f0-9]{32}-[0-9]+\.(webp|jpg)$~D',$v))));}
 public static function enqueue($uploadId,$file){$relative=self::relative($file);if(!$relative)return null;return DB::table(self::TABLE)->insertGetId(['cleanup_key'=>hash('sha256',random_bytes(24).':'.$uploadId.':'.$relative),'upload_id'=>$uploadId,'file_path'=>$relative,'variant_paths'=>json_encode(self::variants($relative)),'available_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}
 private static function codeReferenced($relative,array $variants){if(SavedImageCleanup::codeReferenced($relative,$variants))return true;$needles=[];foreach(array_merge([$relative],$variants)as $v){$needles[]=$v;$needles[]=str_replace('/','\\/',$v);$needles[]=rawurlencode($v);}$bytes=0;$until=microtime(true)+6;$designData=null;$used=[];$dynamic=false;foreach(['app','components','lib','public/legacy/assets']as $folder){$root=dirname(base_path()).'/next-ip/'.$folder;if(!is_dir($root))continue;$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isLink())throw new \RuntimeException('Website code symlink retained.');if(!$f->isFile()||!preg_match('/\.(tsx?|jsx?|json|css|html?)$/iD',$f->getFilename()))continue;$bytes+=$f->getSize();if($f->getSize()>8388608||$bytes>67108864||microtime(true)>$until)throw new \RuntimeException('Website reference scan deferred.');$text=file_get_contents($f->getPathname());if($text===false)throw new \RuntimeException('Website source cannot be checked.');if($f->getPathname()===dirname(base_path()).'/next-ip/lib/original-design.json'){$designData=json_decode($text,true);if(!is_array($designData))throw new \RuntimeException('Website design references cannot be read.');continue;}preg_match_all('/\bdesign\.([A-Za-z_][A-Za-z0-9_]*)/',$text,$properties);foreach($properties[1]as $property)$used[$property]=true;if(preg_match('/\bdesign\s*\[|\bdesign\s+as\s+|\}\s*=\s*design\b/',$text))$dynamic=true;foreach($needles as $n)if(strpos($text,$n)!==false)return true;}}if($designData!==null){$text=json_encode($dynamic?$designData:array_intersect_key($designData,$used),JSON_UNESCAPED_SLASHES);foreach($needles as $n)if(strpos($text,$n)!==false)return true;}return false;}
 private static function quarantine($u){$found=[];foreach(glob(storage_path('app/image-quarantine/'.$u->id.'-*.json'))?:[]as $path){$m=json_decode((string)file_get_contents($path),true);if(is_array($m)&&($m['file']??null)===$u->file_name&&is_file(substr($path,0,-5).'.image'))$found[]=basename($path,'.json');}if(count($found)>1)throw new \RuntimeException('Multiple recovery copies retained for review.');return $found[0]??null;}
 private static function variantsDelete($job,array $variants){foreach($variants as $v){if(!preg_match('~^uploads/optimized/[a-f0-9]{32}-[0-9]+\.(webp|jpg)$~D',$v))throw new \RuntimeException('Unsafe variant retained.');$file=self::local($v);if(is_file($file)&&!unlink($file))throw new \RuntimeException('Variant cleanup needs retry.');}if($job->upload_id){$log=storage_path('app/image-optimization/'.(int)$job->upload_id.'.json');if(is_link($log))throw new \RuntimeException('Diagnostic symlink retained.');if(is_file($log)&&!unlink($log))throw new \RuntimeException('Diagnostic cleanup needs retry.');}ImageVariantManifest::forget($job->file_path);if(is_file(storage_path('app/image-manifests/'.hash('sha256',$job->file_path).'.json')))throw new \RuntimeException('Image manifest cleanup needs retry.');}
 private static function process($job){$variants=json_decode($job->variant_paths?:'[]',true);if(!is_array($variants))throw new \RuntimeException('Media manifest retained for review.');$variants=array_values(array_unique(array_merge($variants,self::variants($job->file_path))));$path=self::local($job->file_path);$u=$job->upload_id?Upload::withTrashed()->find($job->upload_id):null;if($u&&$u->file_name!==$job->file_path)throw new \RuntimeException('Upload changed; retained for review.');$probe=$u?:(object)['id'=>$job->upload_id?:0,'file_name'=>$job->file_path];
  $duplicates=Upload::withTrashed()->where('file_name',$job->file_path);if($u)$duplicates->where('id','!=',$u->id);
  if($duplicates->exists()||UnusedImageCleaner::referenced($probe,(bool)$job->upload_id,[self::TABLE],$variants)||self::codeReferenced($job->file_path,$variants))return 'retained';
  if($u){$reference=self::quarantine($u);try{if(!$reference&&is_file($path))$reference=UnusedImageCleaner::quarantine($u->id,[self::TABLE],true,$variants);if($reference)UnusedImageCleaner::permanent($reference,[self::TABLE],true,$variants);else $u->forceDelete();}catch(\Throwable $e){if($reference&&is_file(storage_path('app/image-quarantine/'.$reference.'.image'))&&Upload::withTrashed()->where('id',$u->id)->exists())UnusedImageCleaner::restore($reference,true);throw $e;}}
  elseif(is_file($path)&&!unlink($path))throw new \RuntimeException('Source cleanup needs retry.');self::variantsDelete($job,$variants);return 'deleted';
 }
 public static function drain($limit=50,array $only=[]){$stats=['deleted'=>0,'retained'=>0,'pending'=>0];if(DB::connection()->transactionLevel()>0)return $stats;$q=DB::table(self::TABLE)->where(function($q){$q->whereNull('available_at')->orWhere('available_at','<=',now());});if($only)$q->whereIn('id',$only);foreach($q->orderBy('id')->limit($limit)->get()as $job){$claimed=DB::table(self::TABLE)->where('id',$job->id)->where(function($q){$q->whereNull('locked_until')->orWhere('locked_until','<',now());})->update(['locked_until'=>now()->addMinutes(10),'updated_at'=>now()]);if(!$claimed)continue;$lock=Cache::lock('image-source-'.hash('sha256',$job->file_path),600);try{if(!$lock->get())throw new \RuntimeException('Another cleanup owns this file.');$state=self::process($job);DB::table(self::TABLE)->where('id',$job->id)->delete();$stats[$state]++;}catch(\Throwable $e){DB::table(self::TABLE)->where('id',$job->id)->update(['attempts'=>DB::raw('attempts+1'),'last_error'=>substr($e->getMessage(),0,300),'available_at'=>now()->addMinute(),'locked_until'=>null,'updated_at'=>now()]);$stats['pending']++;}finally{$lock->release();}}return $stats;}
}
